/// A simple matrix type: `data[r][c]` with `rows` rows and `cols` columns.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Matrix<T> {
    pub data: Vec<Vec<T>>,
    pub rows: usize,
    pub cols: usize,
}

impl<T> Matrix<T> {
    pub fn new(data: Vec<Vec<T>>) -> Self {
        let rows = data.len();
        let cols = if rows == 0 { 0 } else { data[0].len() };
        Matrix { data, rows, cols }
    }
}

pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(!a.is_empty(), "input array must have positive length");
    assert!(shape.len() == 2, "shape must have length 2");
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    assert!(r > 0 && c > 0, "shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must match either R or C for broadcasting"
    );

    let data = if n == r {
        // Treat as column vector: entry(i,j) = a[i]
        let mut m = Vec::with_capacity(r);
        for i in 0..r {
            let v = a[i];
            m.push(vec![v; c]);
        }
        m
    } else {
        // Treat as row vector: entry(i,j) = a[j]
        let mut m = Vec::with_capacity(r);
        for _ in 0..r {
            m.push(a.clone());
        }
        m
    };

    Matrix::new(data)
}